from de import *
T=[]
ZF=['Präsens','Präteritum','Perfekt','Plusquamperfekt','Futur I']
def plusquam(ch,hard):
    t=DT('%s-deu-plusquam'%ch,ch,'Zeitformen','Plusquamperfekt und Futur',seed=131+int(ch[2:]))
    t.th('basis','Zeitformen','Plusquamperfekt: hatte/war + Partizip II (Vorvergangenheit). Futur I: werden + Grundform (Zukunft).')
    THEORY(t,"Bevor der Bus kam, hatte Lena schon gefrühstückt. Und nachher wird sie lernen. Das Verb zeigt, was früher oder später passiert.",SC('talk',t1='Ich hatte schon gegessen.',t2='Ich werde lernen.'),
      "Du kennst jetzt fünf wichtige Zeitformen.",["Zeitform","Bildung","Beispiel"],[["{2|Präsens}","gebeugtes Verb (jetzt)","Ich lache."],["{3|Präteritum}","Vergangenheitsform des Verbs","Ich lachte."],["{1|Perfekt}","haben/sein + Partizip II","Ich habe gelacht."],["{4|Plusquamperfekt}","hatte/war + Partizip II","Ich hatte gelacht."],["{0|Futur I}","werden + Grundform","Ich werde lachen."]],
      "Die Farben zeigen, wie die Form gebaut wird.",
      [([("Ich","",7),("hatte","Hilfsverb",4),("gegessen","Partizip II",4)],"Plusquamperfekt: vor einer anderen Handlung."),([("Er","",7),("war","Hilfsverb",4),("gegangen","Partizip II",4)],"Plusquamperfekt mit «sein»."),([("Wir","",7),("werden","Hilfsverb",0),("spielen","Grundform",0)],"Futur I: Es wird passieren.")],
      "So erkennst du die Zeitform.",["Suche das Verb oder die Verbgruppe.","Steht «werden» + Grundform? Dann ist es Futur.","Steht «hatte» oder «war» + Partizip II? Dann ist es Plusquamperfekt.","Steht «habe» oder «bin» + Partizip II? Dann ist es Perfekt.","Sonst entscheidest du zwischen Präsens und Präteritum."],
      "Das ist wichtig.",[["Plusquamperfekt","Die Handlung war schon vorbei.","Nachdem er gegessen hatte, ging er.",4],["Futur I","Die Handlung kommt noch.","Morgen werde ich lesen.",0],["Hilfsverben","haben, sein, werden","hatte, war, werde",3]],
      fehler=[["Ich werde gegessen.","Ich werde essen.","Futur: werden + Grundform."],["Ich hatte lache.","Ich hatte gelacht.","Plusquamperfekt: hatte + Partizip II."],["Er war gelaufet.","Er war gelaufen.","Das Partizip von laufen ist gelaufen."]])
    if not hard:
        S=[("Ich lache laut.",0),("Ich lachte laut.",1),("Ich habe laut gelacht.",2),("Ich hatte laut gelacht.",3),("Ich werde laut lachen.",4),("Anna spielt Fussball.",0),("Anna spielte Fussball.",1),("Anna hat Fussball gespielt.",2),("Anna hatte Fussball gespielt.",3),("Anna wird Fussball spielen.",4),("Wir gehen heim.",0),("Wir gingen heim.",1),("Wir sind heimgegangen.",2),("Wir waren heimgegangen.",3),("Wir werden heimgehen.",4),("Der Hund bellt.",0),("Der Hund bellte.",1),("Der Hund hatte gebellt.",3),("Der Hund wird bellen.",4),("Tom hat den Brief geschrieben.",2),("Tom hatte den Brief geschrieben.",3),("Tom schrieb den Brief.",1)]
        G=[("Bevor der Bus kam, ___ Lena schon gefrühstückt.","hatte",["wird","hat","werde"]),("Morgen ___ ich meine Grosseltern besuchen.","werde",["hatte","bin","habe"]),("Nachdem wir gegessen ___, gingen wir spielen.","hatten",["werden","wird","sind"]),("Als ich ankam, ___ er schon nach Hause gegangen.","war",["wird","hatte","sind"]),("Nächste Woche ___ wir ins Kino gehen.","werden",["hatten","haben","waren"]),("Sie ___ den Kuchen schon gebacken.","hatte",["wird","werde","wurde"])]
        FX=[("Ich werde lachte.","Ich werde lachen."),("Ich hatte lache.","Ich hatte gelacht."),("Er war gelaufet.","Er war gelaufen."),("Wir werden spielten.","Wir werden spielen."),("Sie hatte gegangen.","Sie war gegangen."),("Du wirst lasen.","Du wirst lesen.")]
        FM=[("Bilde das Futur I: Ich lache.","Ich werde lachen."),("Bilde das Futur: Wir spielen.","Wir werden spielen."),("Bilde das Plusquamperfekt: Ich lachte.","Ich hatte gelacht."),("Bilde das Futur: Er schreibt.","Er wird schreiben."),("Bilde das Plusquamperfekt: Sie spielte.","Sie hatte gespielt."),("Bilde das Futur: Du kommst.","Du wirst kommen.")]
    else:
        S=[("Die Schüler schreiben einen Test.",0),("Die Schüler schrieben einen Test.",1),("Die Schüler haben einen Test geschrieben.",2),("Die Schüler hatten einen Test geschrieben.",3),("Die Schüler werden einen Test schreiben.",4),("Meine Eltern verreisen im Sommer.",0),("Meine Eltern verreisten im Sommer.",1),("Meine Eltern sind im Sommer verreist.",2),("Meine Eltern waren im Sommer verreist.",3),("Meine Eltern werden im Sommer verreisen.",4),("Die Lehrerin erklärt die Regel.",0),("Die Lehrerin hat die Regel erklärt.",2),("Die Lehrerin hatte die Regel erklärt.",3),("Die Lehrerin wird die Regel erklären.",4),("Nachdem der Regen aufgehört hatte, gingen wir hinaus.",3),("Wenn die Sonne untergeht, werden die Sterne sichtbar sein.",4),("Der Zug fuhr pünktlich ab.",1),("Der Zug ist pünktlich abgefahren.",2),("Der Zug war schon abgefahren.",3),("Wir werden die Ergebnisse morgen erfahren.",4),("Wir warteten auf den Zug.",1)]
        G=[("Nachdem die Gäste gegangen ___, räumten wir auf.","waren",["werden","sind","hatten"]),("Wenn es dunkel wird, ___ die Strassenlampen leuchten.","werden",["hatten","waren","haben"]),("Er ___ den Brief schon abgeschickt, bevor sie anrief.","hatte",["wird","hat","wurde"]),("Als ich ankam, ___ der Film schon begonnen.","hatte",["wird","hat","werde"]),("Sie ___ nach Italien gereist, bevor die Grenzen schlossen.","war",["wird","hatte","werden"])]
        FX=[("Wir werden fuhren.","Wir werden fahren."),("Er hatte gelaufet.","Er war gelaufen."),("Ich werde schrieb.","Ich werde schreiben."),("Du hattest gesprochet.","Du hattest gesprochen."),("Nachdem er kam, ging er.","Nachdem er gekommen war, ging er."),("Sie hatte geflogt.","Sie war geflogen.")]
        FM=[("Bilde das Futur: Die Schüler lernen.","Die Schüler werden lernen."),("Bilde das Plusquamperfekt: Er ass.","Er hatte gegessen."),("Bilde das Futur: Wir fahren.","Wir werden fahren."),("Bilde das Plusquamperfekt: Sie ging.","Sie war gegangen."),("Bilde das Futur: Ich schreibe.","Ich werde schreiben."),("Bilde das Plusquamperfekt: Wir sangen.","Wir hatten gesungen.")]
    if hard:more(t,'Nachdem-Sätze','Nach «nachdem» steht oft das Plusquamperfekt, im Hauptsatz das Präteritum oder Perfekt. So zeigst du, was zuerst war.',TBL(['Nebensatz','Hauptsatz','Was war zuerst?'],[['Nachdem er gegessen hatte,','ging er spazieren.','das Essen'],['Nachdem die Gäste gegangen waren,','räumten wir auf.','der Aufbruch']]))
    cls(t,S,ZF,lambda p:"%s\nIn welcher Zeitform steht der Satz?"%p,hint=["Es passiert jetzt.","Es ist vorbei (kurz, mit -te oder Stamm).","haben/sein im Präsens + Partizip II.","hatte/war + Partizip II.","werden + Grundform."],why=lambda p,c:["Präsens: jetzt.","Präteritum: einfache Vergangenheit.","Perfekt: haben/sein + Partizip II.","Plusquamperfekt: hatte/war + Partizip II.","Futur I: werden + Grundform."][c],ne=6,disp=lambda p:p,mq='Tippe alle Sätze im {s} an.',sel=True,sq='Welcher Satz steht im {c}?',sqx='Welcher dieser Sätze steht im {c}?',jnt='Stimmt das? Der Satz steht im {c}.',jnp=True,ntyp=4,ntx=0,mt=2)
    gaps(t,G,ne=3,q='Welche Verbform passt?')
    fixes(t,FX,ne=3,q='Korrigiere die Verbform.')
    forms(t,FM,ne=4,hint='Schreibe den ganzen Satz. Achte auf das Hilfsverb.')
    return t
T+= [lambda:plusquam('kl5',False),lambda:plusquam('kl6',True)]

def hauptsaetze(ch,hard):
    t=DT('%s-deu-hauptsaetze'%ch,ch,'Zeichensetzung','Zwei Hauptsätze trennen',seed=141+int(ch[2:]))
    t.th('basis','Komma zwischen Hauptsätzen','Zwei Hauptsätze trennt man mit einem Komma, wenn sie durch aber, denn, sondern, doch verbunden sind oder ohne Bindewort stehen.')
    THEORY(t,"Du sagst: «Es regnet, aber wir gehen hinaus.» Beide Teile könnten allein stehen. Dazwischen steht ein Komma.",SC('words',words=[['Es regnet','#4285F4'],[',','#EA4335'],['aber','#D93F8E'],['wir gehen hinaus','#34A853']],say='Zwei Sätze, ein Komma'),
      "Ein Hauptsatz hat ein Subjekt und ein Prädikat und kann allein stehen.",["Verbindung","Regel","Beispiel"],[["{1|aber, denn, sondern, doch}","Komma davor","Ich lerne{1|,} denn ich möchte gut sein."],["{0|kein Bindewort}","Komma zwischen den Sätzen","Die Sonne scheint{0|,} es ist warm."],["{2|und, oder}","Komma nicht nötig","Ich lese und sie malt."]],
      "Die zwei Hauptsätze sind farbig.",
      [([("Es regnet","Hauptsatz 1",0),(",","Komma",1),("aber","",6),("wir gehen hinaus","Hauptsatz 2",2)],"Es regnet, aber wir gehen hinaus."),([("Ich bleibe zu Hause","Hauptsatz 1",0),(",","Komma",1),("denn","",6),("ich bin krank","Hauptsatz 2",2)],"Ich bleibe zu Hause, denn ich bin krank."),([("Die Sonne scheint","Hauptsatz 1",0),(",","Komma",1),("es ist warm","Hauptsatz 2",2)],"Ohne Bindewort steht auch ein Komma.")],
      "So setzt du das Komma.",["Suche das Verb in jedem Teil: Gibt es zwei Verben mit eigenem Subjekt?","Prüfe: Kann jeder Teil allein stehen?","Setze ein Komma zwischen die beiden Hauptsätze.","Bei aber, denn, sondern, doch steht das Komma davor."],
      "Das ist wichtig.",[["Hauptsatz","Kann allein stehen.","Es regnet.",0],["Komma","Vor aber, denn, sondern, doch.","…, aber …",1],["Und / oder","Hier ist kein Komma nötig.","Ich lese und sie malt.",2]],
      fehler=[["Es regnet aber wir gehen hinaus.","Es regnet, aber wir gehen hinaus.","Vor «aber» steht ein Komma."],["Ich lerne denn ich will gut sein.","Ich lerne, denn ich will gut sein.","Vor «denn» steht ein Komma."],["Die Sonne scheint es ist warm.","Die Sonne scheint, es ist warm.","Zwei Hauptsätze trennt ein Komma."]])
    if hard:more(t,'Und und oder','Zwischen zwei Hauptsätzen mit «und» oder «oder» darf das Komma fehlen. Es darf aber stehen, wenn der Satz sonst unklar ist.',TBL(['Satz','Komma?'],[['Ich lese und sie malt.','kann fehlen'],['Ich lese, und sie malt.','ist auch möglich']]))
    if not hard:
        P=[("Es regnet","aber","wir gehen hinaus"),("Ich bleibe zu Hause","denn","ich bin krank"),("Tom spielt Fussball","aber","Lisa liest ein Buch"),("Wir gehen nicht ins Kino","sondern","wir bleiben zu Hause"),("Anna ist müde","doch","sie macht ihre Hausaufgaben"),("Ich esse einen Apfel","denn","ich habe Hunger"),("Der Hund bellt","aber","die Katze schläft"),("Wir haben einen Garten","aber","wir haben keinen Hund"),("Die Sonne scheint","","es ist warm"),("Der Wind weht","","die Blätter fallen"),("Mama kocht","","Papa deckt den Tisch"),("Ich mag Tee","aber","ich trinke keinen Kaffee")]
    else:
        P=[("Der Bus hatte Verspätung","aber","wir kamen noch rechtzeitig an"),("Die Schüler schreiben einen Test","denn","die Lehrerin will den Stoff prüfen"),("Wir fahren nicht mit dem Zug","sondern","wir nehmen das Fahrrad"),("Er hatte keine Zeit","doch","er half ihr trotzdem"),("Der Winter ist kalt","","im Sommer ist es heiss"),("Die Kinder bauen eine Hütte","denn","sie wollen im Wald übernachten"),("Meine Schwester lernt Gitarre","aber","ich übe lieber Klavier"),("Die Ferien beginnen morgen","","wir packen schon heute"),("Es schneit seit Stunden","doch","die Strassen sind frei"),("Der Zug fährt ab","","wir haben ihn leider verpasst"),("Die Aufgabe war schwer","aber","alle haben sie gelöst"),("Ich lese ein Buch","denn","ich möchte mehr wissen")]
    def good(a,k,b):return a+', '+(k+' ' if k else '')+b+'.'
    def bad(a,k,b):return a+' '+(k+' ' if k else '')+b+'.'
    ex=5
    for i,(a,k,b) in enumerate(P):
        g=good(a,k,b);bd=bad(a,k,b)
        if i<len(P)-ex:
            t.mc(1 if i<6 else 2,"Welcher Satz ist richtig geschrieben?",g,[bd,a+' '+(k+', ' if k else ', ')+b+'.',a+', '+(k+', ' if k else '')+b+'.'] if k else [bd,a+' ,'+b+'.',a+' '+b+','],"Zwischen den Hauptsätzen steht ein Komma, vor «aber, denn, sondern, doch».")
            t.fix(2,"Setze das Komma an die richtige Stelle.",bd,g,"Vor «%s» steht ein Komma."%k if k else "Zwischen den Hauptsätzen steht ein Komma.",None)
        else:
            t.emc("Welcher Satz ist richtig geschrieben?",g,[bd,a+' '+(k+', ' if k else ', ')+b+'.',a+', '+(k+', ' if k else '')+b+'.'] if k else [bd,a+' ,'+b+'.',a+' '+b+','],'')
            t.efix("Setze das Komma an die richtige Stelle.",bd,g,'')
    cls(t,[x for a,k,b in P for x in ((good(a,k,b),0),(bad(a,k,b),1))],['richtig','falsch'],lambda p:"%s\nSind die Satzzeichen richtig?"%p,hint="Zwischen zwei Hauptsätzen steht ein Komma.",ne=6,sel=False,ntyp=0,ntx=0,match=False,mt=3,jn=0,mq='Tippe alle Sätze an, die {c} sind.')
    return t
T+= [lambda:hauptsaetze('kl5',False),lambda:hauptsaetze('kl6',True)]

def grossklein(ch,hard):
    t=DT('%s-deu-grossklein'%ch,ch,'Rechtschreibung','Gross- und Kleinschreibung',seed=151+int(ch[2:]))
    t.th('basis','Gross oder klein?','Nomen schreibt man gross. Auch Verben und Adjektive werden gross, wenn sie wie Nomen gebraucht werden: das Lesen, etwas Schönes.')
    THEORY(t,"Auf dem Plakat steht: «Beim Lesen vergeht die Zeit schnell.» Das Wort «Lesen» ist ein Verb, aber hier wird es wie ein Nomen gebraucht.",SC('words',words=[['beim','#F29900'],['Lesen','#4285F4'],['vergeht','#EA4335']],say='Verb wird zum Nomen'),
      "Wörter werden zu Nomen, wenn ein Signalwort davor steht.",["Signalwort","Beispiel","Warum gross?"],[["{3|das, beim, zum}","das {0|Lesen}, beim {0|Schwimmen}","Verb als Nomen"],["{3|etwas, nichts, viel}","etwas {0|Schönes}, nichts {0|Neues}","Adjektiv als Nomen"],["{3|alles, wenig, manches}","alles {0|Gute}, wenig {0|Neues}","Mengenwort davor"]],
      "Die Signalwörter sind farbig.",
      [([("Beim","Signalwort",3),("Lesen","Nomen",0),("vergeht","",7),("die","",7),("Zeit","",7)],"Beim Lesen: Verb wird gross."),([("Sie","",7),("möchte","",7),("etwas","Signalwort",3),("Schönes","Nomen",0),("kaufen","",7)],"Etwas Schönes: Adjektiv wird gross."),([("Das","Signalwort",3),("Schwimmen","Nomen",0),("macht","",7),("Spass","",7)],"Das Schwimmen: Verb wird gross.")],
      "So prüfst du die Schreibweise.",["Lies das Wort im Satz.","Steht ein Signalwort davor (das, beim, zum, etwas, nichts, viel)?","Gehört das Wort zu einem Nomen, das danach folgt? Dann bleibt es klein (der schnelle Läufer).","Steht kein Nomen dahinter und wird das Wort wie ein Nomen gebraucht? Dann schreibst du es gross.","Sonst bleibt es klein."],
      "Das ist wichtig.",[["Verb als Nomen","das Lesen, beim Spielen","Gross",0],["Adjektiv als Nomen","etwas Neues, das Gute","Gross",2],["Sonst klein","Ich lese gern.","klein",1]],
      fehler=[["beim lesen","beim Lesen","Signalwort «beim»: Verb wird gross."],["etwas schönes","etwas Schönes","Signalwort «etwas»: Adjektiv wird gross."],["der Schnelle Läufer","der schnelle Läufer","«schnelle» beschreibt «Läufer» und bleibt klein."]])
    if hard:more(t,'Tageszeiten und Sprachen','Auch hier hilft ein Signalwort: heute Abend, auf Deutsch, im Allgemeinen. Gross schreibst du dann das Wort nach dem Signalwort.',TBL(['Signalwort + Wort','Gross oder klein?'],[['heute {0|Abend}','Abend ist Tageszeit nach «heute»: gross'],['auf {0|Deutsch}','Sprache nach «auf»: gross'],['im {0|Allgemeinen}','feste Wendung: gross']]))
